create table if not exists public.buildpulse_story_enrichment_claims(story_id uuid primary key references public.buildpulse_stories(id) on delete cascade,state text not null default 'queued' check(state in('queued','processing','completed','failed')),queued_at timestamptz not null default now(),updated_at timestamptz not null default now(),attempts integer not null default 0,last_error text);
alter table public.buildpulse_story_enrichment_claims enable row level security;revoke all on public.buildpulse_story_enrichment_claims from anon,authenticated;grant all on public.buildpulse_story_enrichment_claims to service_role;
create or replace function public.buildpulse_enqueue_story_enrichment(p_limit integer default 25) returns integer language plpgsql security definer set search_path=public,pgmq as $$declare r record;n integer:=0;begin for r in select s.id,s.title,s.summary,s.category,s.canonical_source_url,s.image_url,s.published_at from public.buildpulse_stories s where s.verification_state='verified' and coalesce(s.publication_state,'')<>'withheld' and not exists(select 1 from public.buildpulse_story_articles a where a.story_id=s.id) and not exists(select 1 from public.buildpulse_story_enrichment_claims c where c.story_id=s.id and c.state in('queued','processing','completed')) order by s.published_at desc nulls last limit greatest(1,least(coalesce(p_limit,25),100)) loop insert into public.buildpulse_story_enrichment_claims(story_id,state) values(r.id,'queued') on conflict(story_id) do update set state='queued',queued_at=now(),updated_at=now(),attempts=0,last_error=null;perform pgmq.send('buildpulse_story_enrichment',jsonb_build_object('story_id',r.id,'title',r.title,'summary',r.summary,'category',r.category,'canonical_source_url',r.canonical_source_url,'image_url',r.image_url,'published_at',r.published_at,'enqueued_at',now()));n:=n+1;end loop;return n;end$$;
create or replace function public.buildpulse_read_story_enrichment(p_qty integer default 3,p_visibility_seconds integer default 300) returns table(msg_id bigint,read_ct integer,enqueued_at timestamptz,vt timestamptz,message jsonb) language sql security definer set search_path=public,pgmq as $$select r.msg_id,r.read_ct,r.enqueued_at,r.vt,r.message from pgmq.read('buildpulse_story_enrichment',greatest(30,least(coalesce(p_visibility_seconds,300),1800)),greatest(1,least(coalesce(p_qty,3),10))) r$$;
create or replace function public.buildpulse_archive_story_enrichment(p_msg_id bigint) returns boolean language sql security definer set search_path=public,pgmq as $$select pgmq.archive('buildpulse_story_enrichment',p_msg_id)$$;